/*!40000 ALTER TABLE `grammar_lesson_sections` DISABLE KEYS */;
INSERT INTO `grammar_lesson_sections` VALUES (1,1,'一般现在时','表示经常性动作/真理。主语为第三人称单数时动词加 -s/-es。\n例: He goes to school every day. / Water boils at 100°C.',1),(2,1,'现在进行时','am/is/are + V-ing, 表示正在进行的动作。\n例: I am reading a book now. / They are playing football.',2),(3,1,'现在完成时','have/has + 过去分词。标志词: already, yet, since, for, ever, never。\n例: She has already finished her homework. / I have never been to Japan.',3),(4,1,'现在完成进行时','have/has been + V-ing。强调从过去持续到现在的动作。\n例: I have been studying English for 3 hours.',4),(5,1,'一般过去时','动词过去式。标志词: yesterday, last week, ago, in 2020。\n例: They arrived at 9 o\'clock yesterday. / I visited Paris last summer.',5),(6,1,'过去进行时','was/were + V-ing。表示过去某个时间点正在做的事。\n例: I was sleeping when you called.',6),(7,1,'过去完成时','had + 过去分词。表示\"过去的过去\"。\n例: When I arrived, she had already left.',7),(8,1,'一般将来时','will + 动词原形 或 be going to + 动词原形。\n例: I will call you tomorrow. / It is going to rain.',8),(9,2,'时间介词','at (具体时刻), on (具体某天), in (较长时段)。\n例: at 8:00 / on Monday / in July / at night / on weekends / in the morning',1),(10,2,'地点介词','at (具体地点), on (在...上面), in (在...里面), by (在...旁边)。\n例: at the station / on the table / in the room',2),(11,2,'固定搭配 (高频)','good at / interested in / look forward to / belong to / depend on / angry with / afraid of / famous for / different from / agree with / apply for / care about / consist of / dream of / insist on / lead to / rely on / suffer from / wait for',3),(12,2,'易混介词辨析','in vs into (静态vs动态): She is in the room. vs She walked into the room.\nat vs to (方向): He threw the ball at me. vs He threw the ball to me.\nfor vs since: for + 时间段 / since + 时间点',4),(13,3,'不定冠词 a/an','a + 辅音开头, an + 元音开头。用于首次提到的单数可数名词。\n例: a book / an apple / a university / an hour (h不发音)',1),(14,3,'定冠词 the','特指/第二次提到/独一无二的事物。\n例: The sun rises in the east. / I saw a dog. The dog was big.',2),(15,3,'零冠词 (不用冠词)','复数泛称 / 不可数名词泛称 / 专有名词 / 三餐/球类/学科前。\n例: I like music. / Dogs are loyal. / I have lunch at noon. / She plays tennis.',3),(16,3,'常见错误','I saw dog. -> I saw a dog.\nSun is bright. -> The sun is bright.\nThe life is beautiful. -> Life is beautiful. (泛称)',4),(17,4,'陈述句语序','英语基本语序: SVO (主-谓-宾) + 状语\n例: I (S) ate (V) an apple (O) yesterday (状语).\n时间顺序: 方式 → 地点 → 时间',1),(18,4,'疑问句语序','一般疑问句: 助动词 + 主语 + 动词\n例: Do you like coffee? / Have you been to Japan?\n特殊疑问句: 疑问词 + 助动词 + 主语 + 动词',2),(19,4,'倒装句 (进阶)','否定词置于句首时需倒装:\n例: Never have I seen such beauty. / Not only does he sing, but he also dances.\nOnly then did I realize my mistake.',3),(20,5,'基本结构','be + 过去分词 (by 动作执行者)。\n例: The letter was written by Tom. (Tom wrote the letter.)',1),(21,5,'时态变化','现在: is/are written / 过去: was/were written\n完成: has/have been written / 将来: will be written',2),(22,5,'使用场景','1. 不知道或不关心谁做的: The window was broken.\n2. 强调承受者: English is spoken worldwide.\n3. 正式/科学文体: The experiment was conducted.',3),(23,6,'与现在相反','If + 主语 + 过去式, 主语 + would/could/might + V原\n例: If I were you, I would apologize. (现在事实: 我不是你)',1),(24,6,'与过去相反','If + 主语 + had done, 主语 + would/could/might + have done\n例: If I had known, I would have come earlier.',2),(25,6,'wish 用法','wish + 过去式(与现在相反) / wish + had done(与过去相反)\n例: I wish I were taller. / I wish I had studied harder.',3),(26,7,'can/could','能力/可能性 (could是can的过去式或更委婉)\n例: I can swim. / Could you help me? (礼貌请求)',1),(27,7,'must/have to','must = 主观必须; have to = 客观必须。must not = 禁止; don\'t have to = 不必\n例: You must go now. / I have to wear a uniform.',2),(28,7,'should/ought to','应该(建议)。should have done = 本应该做(但没做)\n例: You should see a doctor. / I should have studied harder.',3),(29,7,'may/might','可能性(50%以下)。may = 也用于正式允许。\n例: It may rain tomorrow. / May I come in?',4),(30,8,'定语从句','who/whom(人) which(物) that(人/物) whose(所有格)\n例: The man who lives next door is a doctor.',1),(31,8,'that vs which','限制性从句用 that: I like books that are funny.\n非限制性用 which: This book, which I bought online, is great.',2),(32,8,'状语从句','时间: when/while/before/after/since\n原因: because/since/as\n让步: although/even though\n条件: if/unless/provided that',3),(33,8,'名词性从句','主语从句: What he said was true.\n宾语从句: I know that you are right.\n表语从句: The problem is that we have no time.',4),(34,9,'比较级','短词+er / 长词 more + 原级 + than\n例: She is taller than me. / This is more interesting than that.\nas...as 同级比较: He is as tall as his brother.',1),(35,9,'最高级','短词+est / 长词 the most + 原级\n例: She is the tallest in class. / This is the most beautiful view.',2),(36,9,'特殊变化','good→better→best / bad→worse→worst / many→more→most / little→less→least / far→farther/further',3),(37,10,'零类条件句 (事实)','If + 一般现在时, 一般现在时\n例: If you heat ice, it melts.',1),(38,10,'第一类条件句 (真实将来)','If + 一般现在时, will + V原\n例: If it rains tomorrow, I will stay home.',2),(39,10,'第二类条件句 (现在虚拟)','If + 过去式, would + V原\n例: If I had a million dollars, I would travel the world.',3),(40,10,'unless / as long as','unless = if not (除非)\n例: You won\'t pass unless you study. / As long as you try, you will succeed.',4),(41,11,'长难句方法论','拆解长难句四步法:\n1. 找主干: 主语+谓语(+宾语)，忽略修饰成分\n2. 识别从句: that/which/who/what/when/where等引导词\n3. 析分词结构: -ing(主动) / -ed(被动) 分词短语作定语或状语\n4. 理逻辑: 找到连接词(and/but/because)明确各部分关系',1),(42,11,'嵌套从句型','特征: 从句中包含从句，多层嵌套。\n标志: What...is that... / The fact that...means that...\n示例: What makes this discovery remarkable is not merely its scientific significance, but rather the way in which it was achieved.\n拆解: What主语从句 + is系动词 + the way(表语) + in which定语从句',2),(43,11,'长状语前置型','特征: 分词完成式/介词短语放在句首作状语。\n标志: Having done... / Despite... / Given...\n示例: Having spent a decade cataloguing the migratory patterns, the biologist was able to present findings that challenged prevailing theories.\n拆解: Having spent...分词状语 + 主句biologist was able to... + that定语从句',3),(44,11,'倒装虚拟型','特征: 省略if的虚拟条件句，助动词提到句首。\n标志: Had... / Were... / Should...\n示例: Had I known the truth, I would never have agreed.\n拆解: Had I known... = If I had known... + 主句would have agreed',4),(45,11,'强调与否定前置型','特征: It is not until...that... / Not only...but also...\n示例: It was not until the 20th century that the concept of a global economy began to take shape.\n拆解: 强调句型 It is not until + 时间 + that + 正常语序句',5),(46,11,'同位语插入型','特征: 破折号/逗号包裹的插入成分。\n示例: The long-term implications of her work — assuming, of course, that the theories prove correct — could transform the way we process information.\n拆解: 主句implications could transform... + 插入条件assuming that...',6),(47,12,'は (主题)','提示主题，读作 wa。\n例: 私は学生です。(我是学生)',1),(48,12,'が (主语/对象)','表示主语或好恶、能力的对象。\n例: 日本語が好きです。(我喜欢日语) / 彼が来ました。(他来了)',2),(49,12,'を (宾语)','表示动作的直接对象。\n例: 本を読みます。(读书)',3),(50,12,'に (方向/时间/对象)','表示方向、时间点、动作对象。\n例: 学校に行きます。(去学校) / 6時に起きます。(6点起床)',4),(51,12,'で (场所/手段)','表示动作场所或手段。\n例: バスで行きます。(坐公交去) / 公園で遊ぶ。(在公园玩)',5),(52,12,'の (所属)','表示所属或同位。\n例: 私の本 (我的书) / 日本語の先生 (日语老师)',6),(53,12,'と・や・か (并列/列举/疑问)','と=完全列举、や=部分列举、か=选择疑问。\n例: りんごとバナナ / りんごやバナナ / りんごかバナナ',7),(54,13,'ます形 (礼貌形)','动1: 词尾う段→い段+ます (書く→書きます)\n动2: 去る+ます (食べる→食べます)\n动3: する→します / 来る→来ます(きます)',1),(55,13,'て形 (连接形)','动1: く→いて / ぐ→いで / す→して / ぬぶむ→んで / るつう→って\n动2: 去る+て\n动3: して / きて',2),(56,13,'た形 (过去形)','将て形中的て/で换成た/だ即可。\n例: 食べて→食べた / 書いて→書いた',3),(57,13,'ない形 (否定形)','动1: 词尾う段→あ段+ない (書く→書かない)\n动2: 去る+ない (食べる→食べない)\n动3: しない / こない',4),(58,13,'辞書形 (原形)','即动词的基本形，用于能力/喜好的表达。\n例: 泳ぐことができる (会游泳)',5),(59,13,'意向形・命令形','意向(劝诱): 行こう / 食べよう\n命令: 行け / 食べろ',6),(60,14,'い形容词','以「い」结尾。\n现在肯定: 高いです·现在否定: 高くないです\n过去肯定: 高かったです·过去否定: 高くなかったです',1),(61,14,'な形容词','接名词时加「な」。\n现在肯定: 静かです·现在否定: 静かじゃないです\n过去肯定: 静かでした·过去否定: 静かじゃなかったです',2),(62,15,'尊敬語','抬高对方。お/ご + 动词连用形 + になる\n例: お待ちください (请稍等) / いらっしゃいます (在/来/去)',1),(63,15,'謙譲語','降低自己。お/ご + 动词连用形 + する\n例: お送りします (我给您送) / 申します (我说/我叫)',2),(64,15,'丁寧語','です・ます体，通用礼貌表达。',3),(65,16,'～たい (想做)','动词连用形 + たい。\n例: 日本に行きたいです。(想去日本)',1),(66,16,'～たことがある (有过经历)','动词た形 + ことがある。\n例: 富士山に登ったことがある。(爬过富士山)',2),(67,16,'～なければならない (必须)','动词ない形(去い) + ければならない。\n例: 勉強しなければならない。(必须学习)',3),(68,16,'～てもいい (可以)','て形+もいい。\n例: 写真を撮ってもいいですか。(可以拍照吗？)',4),(69,16,'～てはいけない (禁止)','て形+はいけない。\n例: ここでタバコを吸ってはいけません。(这里不能吸烟。)',5),(70,17,'日语句子拆解法','拆解四步法:\n1. 找句末谓语: 日语谓语在句末，先定位\n2. 识助词: は/が(主语) を(宾语) に/で(状语) の(定语)\n3. 定修饰关系: 连体形(名词前)修饰名词，连用形连接各分句\n4. 辨转折递进: が/しかし(转折) そして/また(并列) なぜなら(原因)',1),(71,17,'多重修饰语型','特征: 名词前堆叠多层定语从句。\n示例: この小説の主人公が、過酷な環境に抗うことなく、自分にできる精一杯のことを成し遂げようとする姿には、深い感銘を受けた。\n拆解: 姿(主题) + に(助词) + 感銘を受けた(谓语)。「姿」前所有内容都是连体修饰。',2),(72,17,'转折嵌套型','特征: ～のであるが / ～ものの / ～とはいえ\n示例: 政府は改革案を提出せざるを得なかったのであるが、野党側はその案が負担を強いるものであるとして強く反発した。\n拆解: 主句1(提出せざるを得なかった) + 转折(のであるが) + 主句2(反発した)。中间夹了引用(～として)。',3),(73,17,'～という同位型','特征: 用という概括前文或下定义。\n示例: 異文化に身を置くということは、価値観そのものを問い直す作業でもあった。\n拆解: ～ということ/というのは = 下定义句式，「所谓...就是...」',4),(74,17,'句末多层推量型','特征: 句末堆叠多个助动词和表达。\n示例: ～なければならないだろうと考えられる。\n拆解: なければ(否定条件) + ならない(必须) + だろう(推测) + と考えられる(被认为)。逐层剥开。',5),(75,18,'이/가 (主格)','有收音+이, 无收音+가。表示主语。\n例: 날씨가 좋아요.(天气好) / 책이 있어요.(有书)',1),(76,18,'은/는 (主题)','有收音+은, 无收音+는。表示主题或对比。\n例: 저는 학생이에요.(我是学生)',2),(77,18,'을/를 (宾格)','有收音+을, 无收音+를。表示宾语。\n例: 밥을 먹어요.(吃饭) / 커피를 마셔요.(喝咖啡)',3),(78,18,'에 (时间/地点)','表示时间点或目的地。\n例: 학교에 가요.(去学校) / 7시에 일어나요.(7点起床)',4),(79,18,'에서 (场所/从)','表示动作场所或出发点。\n例: 집에서 공부해요.(在家学习) / 서울에서 왔어요.(从首尔来)',5),(80,18,'의 (所属)','表示所属。口语中常读作에。\n例: 나의 가족 (我的家人)',6),(81,19,'요形 (口语礼貌)','아/어요: 词干末元音ㅏㅗ→아요, 其他→어요, 하→해요。\n例: 가다→가요 / 먹다→먹어요 / 하다→해요',1),(82,19,'ㅂ니다形 (正式)','有收音+습니다, 无收音+ㅂ니다。\n例: 먹다→먹습니다 / 가다→갑니다',2),(83,19,'过去时','았/었어요: 规则同아/어요，加ㅆ。\n例: 가다→갔어요 / 먹다→먹었어요',3),(84,19,'将来时','ㄹ/을 거예요: 有收音+을, 无收音+ㄹ。\n例: 할 거예요.(会做的) / 먹을 거예요.(会吃的)',4),(85,20,'시 (主体敬语)','动词词干 + (으)시 + 语尾。\n例: 오다→오세요 / 읽다→읽으세요',1),(86,20,'特殊敬语词','있다→계시다 / 먹다→드시다 / 자다→주무시다 / 말하다→말씀하시다',2),(87,21,'안 + 动词','简单否定，用于口语。\n例: 안 먹어요.(不吃) / 안 가요.(不去)',1),(88,21,'지 않다','正式否定。\n例: 먹지 않아요.(不吃) / 크지 않아요.(不大)',2),(89,21,'못 + 动词','表示\"不能/不会\"。\n例: 못 와요.(来不了) / 못 먹어요.(吃不了)',3),(90,22,'韩语句子拆解法','步骤:\n1. 先找句末谓语(动词/形容词+语尾)\n2. 用助词断句: 이가은는(主语) 을를(宾语) 에에서(状语)\n3. 找连接语尾: 고(并列) 지만(转折) 면서(同时) 니까(原因)\n4. 处理冠形词形: 는/은/을 + 名词 = 定语从句',1),(91,22,'多重조사堆叠型','特征: 多个助词连续出现。\n示例: 학교에서의 생활은 힘들지만 보람이 있다.\n拆解: 학교에서(场所) + 의(所属) = 학교에서의(在学校方面的) + 생활은(主题) + 힘들지만(转折) + 보람이 있다(有意义)',2),(92,22,'冠形词嵌套型','特征: 定语从句中嵌套定语从句。\n示例: 내가 가장 좋아하는 사람이 내게 해 준 말을 잊을 수 없다.\n拆解: 내가 좋아하는(定语) 사람이(主) 해 준(定语) 말을(宾) 잊을 수 없다(谓)',3),(93,22,'条件-让步复合型','特征: -도/어도 + -지만 复合。\n示例: 비록 힘들다고는 하지만 포기할 수는 없다.\n拆解: 비록...지만 = \"虽然...但是\"框架 + 는 수가 없다 = \"不可能/不会\"',4),(94,23,'-er 动词 (第一组)','parler: je parle / tu parles / il parle / nous parlons / vous parlez / ils parlent\n规律: 去 -er + 词尾 -e/-es/-e/-ons/-ez/-ent',1),(95,23,'-ir 动词 (第二组)','finir: je finis / tu finis / il finit / nous finissons / vous finissez / ils finissent',2),(96,23,'-re 动词 (第三组)','attendre: j\'attends / tu attends / il attend / nous attendons / vous attendez / ils attendent',3),(97,23,'核心不規則','être: suis/es/est/sommes/êtes/sont\navoir: ai/as/a/avons/avez/ont\naller: vais/vas/va/allons/allez/vont\nfaire: fais/fais/fait/faisons/faites/font',4),(98,24,'定冠词','le (阳单) / la (阴单) / l\' (元音前) / les (复数)\n例: le livre / la table / l\'école / les enfants',1),(99,24,'不定冠词','un (阳单) / une (阴单) / des (复数)\n例: un chat / une fleur / des amis',2),(100,24,'部分冠词','du (阳) / de la (阴) / de l\' (元音前)\n例: du pain / de la soupe / de l\'eau',3),(101,25,'性数配合','阳性→阴性: 一般+e (grand→grande)\n单数→复数: 一般+s\n不規則: beau→belle / blanc→blanche / bon→bonne',1),(102,25,'位置','大多数在名词后: une robe rouge (红裙子)\n少数在名词前: beau, bon, grand, petit, jeune, vieux, nouveau',2),(103,26,'Présent (现在时)','表示现在发生的动作或状态。\n例: Je mange une pomme.(我在吃苹果)',1),(104,26,'Passé Composé (复合过去)','avoir/être(现在时) + 过去分词。\n例: J\'ai mangé.(我吃了) / Elle est allée.(她去了)',2),(105,26,'Imparfait (未完成过去)','词干( nous 形去 -ons) + -ais/-ais/-ait/-ions/-iez/-aient\n用于描述/习惯/背景。',3),(106,26,'Futur Simple (简单将来)','动词不定式 + -ai/-as/-a/-ons/-ez/-ont\n例: Je parlerai.(我将说) / Nous irons.(我们将去)',4),(107,27,'否定','ne + 动词 + pas / plus / jamais / rien。\n例: Je ne mange pas.(我不吃) / Je ne sais rien.(我什么都不知道)',1),(108,27,'疑问','三种方式:\n1. 语调上升: Tu viens?\n2. Est-ce que: Est-ce que tu viens?\n3. 倒装: Viens-tu?',2),(109,28,'法语句子拆解法','步骤:\n1. 找变位动词(谓语)，一个从句一个谓语\n2. 识别关系代词: qui(主) que(宾) dont(的) où(地点)\n3. 处理副动词/分词: en+现在分词 / 复合过去分词\n4. 逻辑连接词: bien que+虚拟 / car(因为) / alors que(而)',1),(110,28,'Bien que虚拟让步型','特征: Bien que + 虚拟式 + 主句。\n示例: Bien que les progrès aient amélioré notre qualité de vie, il serait naïf de croire que ces avancées sont sans conséquences.\n拆解: Bien que让步 + 主句il serait naïf + de croire que宾从',2),(111,28,'Ce qui/que...c\'est强调型','特征: 用ce qui/que引出主语从句。\n示例: Ce qui rend cette oeuvre unique, c\'est la manière dont l\'auteur parvient à entrelacer le destin de ses personnages avec l\'histoire.\n拆解: Ce qui主语从句 + c\'est系词 + 表语la manière + dont定语从句',3),(112,29,'Nominativ (一格·主格)','主语。\n阳性: der/ein · 阴性: die/eine · 中性: das/ein · 复数: die\n例: Der Mann ist hier.',1),(113,29,'Akkusativ (四格·宾格)','直接宾语/方向。\n阳性: den/einen · 阴性: die/eine · 中性: das/ein · 复数: die\n例: Ich sehe den Mann.',2),(114,29,'Dativ (三格·与格)','间接宾语/静态位置。\n阳性: dem/einem · 阴性: der/einer · 中性: dem/einem · 复数: den +名词+n\n例: Ich gebe dem Mann das Buch.',3),(115,29,'Genitiv (二格·属格)','所属关系。\n阳性: des/eines · 阴性: der/einer · 中性: des/eines\n例: Das Auto des Mannes.',4),(116,30,'主句: 动词第二位','动词永远在第二位。\n例: Morgen gehe ich ins Kino. / Ich gehe morgen ins Kino.',1),(117,30,'从句: 动词末位','在 dass/weil/wenn 从句中动词放句末。\n例: Ich weiß, dass er heute kommt.',2),(118,30,'时间-方式-地点','多个状语时的自然顺序。\n例: Ich fahre morgen mit dem Zug nach Berlin.',3),(119,31,'现在时人称变位','machen: ich mache / du machst / er macht / wir machen / ihr macht / sie machen',1),(120,31,'可分动词','前缀分离置于句末。\n例: aufstehen → Ich stehe um 7 Uhr auf. / anrufen → Ich rufe dich an.',2),(121,31,'现在完成时','haben/sein + 第二分词。\n例: Ich habe gearbeitet. / Ich bin gegangen.',3),(122,31,'情态动词','können/müssen/dürfen/wollen/sollen/möchten + 动词原形(句末)。\n例: Ich kann gut schwimmen.',4),(123,32,'弱变化 (定冠词后)','定冠词已体现性数格，形容词词尾简化为 -e 或 -en。\n例: der große Mann / die schöne Frau / das kleine Kind',1),(124,32,'强变化 (零冠词)','形容词承担性数格标记: -er/-e/-es 等。\n例: guter Wein / frische Milch / kaltes Wasser',2),(125,33,'+Akk 介词','durch(穿过) / für(为了) / gegen(反对) / ohne(没有) / um(围绕)\n例: für dich / ohne mich',1),(126,33,'+Dat 介词','aus(来自) / bei(在...旁) / mit(和...一起) / nach(朝/之后) / seit(自从) / von(从) / zu(去)\n例: mit dem Bus / nach der Arbeit',2),(127,33,'双格介词','in/an/auf/über/unter/hinter/neben/vor/zwischen\n静态+Dat / 动态+Akk\n例: in der Schule(在-静) / in die Schule(去-动)',3),(128,34,'德语句子拆解法','步骤:\n1. 找变位动词(句2位置或句末)\n2. 判断主从句: 看引导词(dass/weil/wenn/obwohl)和动词位置\n3. 找可分前缀(句末)\n4. 处理格与形容词词尾，确定名词的语法角色\n5. 理情态动词+实义动词(句末)的关系',1),(129,34,'框架结构型','特征: 助动词+句末补足成分构成\"框架\"。\n示例: Die Bundesregierung hat in den vergangenen Jahren zahlreiche Maßnahmen ergriffen, um den CO2-Ausstoß zu reduzieren.\n拆解: hat...ergriffen(框架谓语) + um...zu不定式(目的)',2),(130,34,'从句嵌套型','特征: dass/was/obwohl从句中还有dass从句。\n示例: was darauf hindeutet, dass die bisherigen Anstrengungen bei weitem nicht ausreichen, um die Klimaziele zu erreichen.\n拆解: was(关系代词指代前句) + hindeutet, dass(宾从) + ausreichen, um...zu(目的)',3),(131,34,'虚拟倒装条件型','特征: 省略wenn的虚拟条件句。\n示例: Hätte man den Forschern vor zwanzig Jahren gesagt, dass es möglich sein würde, so hätten die meisten dies für Science-Fiction gehalten.\n拆解: Hätte...gesagt(倒装条件=Wenn man gesagt hätte) + dass宾从 + so hätten...gehalten(主句)',4);
