m/all?keyword=法语否定疑问'),(28,'fr','长难句精析',6,'https://search.bilibili.com/all?keyword=法语长难句'),(29,'de','格 (Kasus)',1,'https://search.bilibili.com/all?keyword=德语格 语法'),(30,'de','词序 (Wortstellung)',2,'https://search.bilibili.com/all?keyword=德语句子结构 语序'),(31,'de','动词 (Verben)',3,'https://search.bilibili.com/all?keyword=德语动词'),(32,'de','形容词变格',4,'https://search.bilibili.com/all?keyword=德语形容词变格'),(33,'de','常用介词',5,'https://search.bilibili.com/all?keyword=德语介词'),(34,'de','长难句精析',6,'https://search.bilibili.com/all?keyword=德语长难句');
