INSERT INTO `grammar_practices` VALUES (1,'en',0,'fill','He ___ (go) to school every day.','goes','三单','一般现在时主语为第三人称单数时动词加 -s/-es',1),(2,'en',0,'fill','She ___ (be) a student.','is','be动词','主语she用is',2),(3,'en',0,'fill','They ___ (play) football now.','are playing','现在进行时','am/is/are + V-ing',3),(4,'en',0,'fill','I am good ___ math.','at','固定搭配','be good at',4),(5,'en',0,'fill','She is interested ___ art.','in','固定搭配','be interested in',5),(6,'en',0,'fill','We ___ (not/see) that movie yet.','have not seen','现在完成时否定','have not + 过去分词',6),(7,'en',0,'fill','___ you ___ (ever/be) to Japan?','Have; been','现在完成时疑问','Have + 主语 + 过去分词',7),(8,'en',0,'fill','She ___ (watch) TV every evening.','watches','三单','watch→watches (以ch结尾加-es)',8),(9,'en',0,'fill','There ___ (be) a book on the desk.','is','there be句型','单数用is',9),(10,'en',0,'correct','He go to school every day.','goes','三单错误','一般现在时三单加s/es',1),(11,'en',0,'correct','She are a teacher.','is','be动词错误','主语she对应is',2),(12,'en',0,'correct','I am good in music.','at','介词错误','good at是固定搭配',3),(13,'en',0,'correct','We did not went to the park.','go','过去时错误','did not + 动词原形',4),(14,'en',1,'fill','The book ___ (write) by Mark Twain.','was written','被动·过去','was/were + 过去分词',1),(15,'en',1,'fill','When I arrived, she ___ (already/leave).','had already left','过去完成','had + 过去分词',2),(16,'en',1,'fill','English ___ (speak) worldwide.','is spoken','被动·现在','am/is/are + 过去分词',3),(17,'en',1,'fill','The man ___ (stand) there is my uncle.','standing','现在分词作定语','主动用-ing',4),(18,'en',1,'fill','If I ___ (be) you, I ___ (apologize).','were; would apologize','虚拟语气','与现在相反: If + 过去式, would + 原形',5),(19,'en',1,'fill','She is the girl ___ won the first prize.','who','关系代词','who指代人',6),(20,'en',1,'fill','I look forward ___ hearing from you.','to','固定搭配','look forward to + doing',7),(21,'en',1,'correct','The letter was wrote by him.','written','过去分词错误','write→wrote→written',1),(22,'en',1,'correct','When I came, she left already.','had already left','时态错误