--
-- Table structure for table `language`
--

DROP TABLE IF EXISTS `language`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `language` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `code` varchar(10) NOT NULL COMMENT '语种代码 (如 en, fr, ja, ko, de)',
  `name_cn` varchar(50) NOT NULL COMMENT '语种中文名 (如 英语, 法语, 日语)',
  `name_native` varchar(50) NOT NULL COMMENT '语种原生名 (如 English, Français, 日本語)',
  `flag_icon` varchar(255) DEFAULT NULL COMMENT '国旗图标URL',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_deleted` tinyint(4) NOT NULL DEFAULT '0' COMMENT '逻辑删除标志',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_code` (`code`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COMMENT='语种字典表';
/*!40101 SET character_set_client = @saved_cs_client */;

