/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `user_progress` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) NOT NULL COMMENT '用户ID',
  `vocab_id` bigint(20) NOT NULL COMMENT '单词ID',
  `lesson_id` bigint(20) DEFAULT NULL COMMENT '课时ID',
  `lang_code` varchar(10) NOT NULL COMMENT '语种代码 (冗余字段，加速按语种统计进度)',
  `status` tinyint(4) DEFAULT '0' COMMENT '学习状态 (0:新词 1:学习中 2:已掌握 3:需复习)',
  `familiarity` int(11) DEFAULT '0' COMMENT '熟悉度 (0-5)',
  `review_count` int(11) DEFAULT '0' COMMENT '已复习次数',
  `last_review_time` datetime DEFAULT NULL COMMENT '上次复习时间',
  `next_review_time` datetime DEFAULT NULL COMMENT '下次复习时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_deleted` tinyint(4) NOT NULL DEFAULT '0' COMMENT '逻辑删除标志',
  `hesitation_ms` int(11) DEFAULT '0' COMMENT '平均犹豫时长(毫秒)',
  `mastery_level` tinyint(4) DEFAULT '0' COMMENT '掌握等级 0=新词 1=学习中 2=熟悉 3=已掌握',
  `error_tags` varchar(500) DEFAULT NULL COMMENT '错误标签JSON数组',
  `last_hesitation_at` datetime DEFAULT NULL COMMENT '最近一次犹豫时间',
  `ease_factor` double DEFAULT '2.5' COMMENT 'SM-2 难度因子(1.3~2.5)',
  `stability` int(11) DEFAULT '0' COMMENT '稳定性(连续正确次数)',
  `consecutive_correct` int(11) DEFAULT '0' COMMENT '连续正确次数',
  `interval_days` int(11) DEFAULT '0' COMMENT 'SM-2 上次复习间隔天数',
  `repetition` int(11) DEFAULT '0' COMMENT 'SM-2 重复次数',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_vocab` (`user_id`,`vocab_id`),
  KEY `idx_user_lang_review` (`user_id`,`lang_code`,`next_review_time`),
  KEY `idx_user_mastery` (`user_id`,`mastery_level`)
) ENGINE=InnoDB AUTO_INCREMENT=63 DEFAULT CHARSET=utf8mb4 COMMENT='用户学习进度表';
