--
-- Table structure for table `vocabulary`
--

DROP TABLE IF EXISTS `vocabulary`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `vocabulary` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `lang_code` varchar(10) NOT NULL COMMENT '所属语种',
  `lesson_id` bigint(20) DEFAULT NULL,
  `word` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `phonetic` varchar(100) DEFAULT NULL COMMENT '音标/假名 (英语存IPA音标，日语存假名，法语存IPA)',
  `romanization` varchar(150) DEFAULT NULL COMMENT '罗马音/拼音 (日语罗马音 taberu, 韩语罗马音 sagwa, 汉语拼音)',
  `definition` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `example_sentence` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `example_translation` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `audio_url` varchar(255) DEFAULT NULL COMMENT '发音音频URL',
  `part_of_speech` varchar(50) DEFAULT NULL COMMENT '词性 (如 n.名词, v.动词)',
  `level` varchar(30) DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_deleted` tinyint(4) NOT NULL DEFAULT '0' COMMENT '逻辑删除标志',
  PRIMARY KEY (`id`),
  KEY `idx_lang_word` (`lang_code`,`word`),
  KEY `idx_pos` (`part_of_speech`),
  KEY `idx_level` (`level`),
  KEY `idx_lang_level` (`lang_code`,`level`)
) ENGINE=InnoDB AUTO_INCREMENT=4150 DEFAULT CHARSET=utf8mb4 COMMENT='多语种词汇信息表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `vocabulary`
--

LOCK TABLES `vocabulary` WRITE;
/*!40000 ALTER TABLE `vocabulary` DISABLE KEYS */;
INSERT INTO `vocabulary` VALUES (1,'en',1,'hello','/həLOʊ/',NULL,'你好，用于打招呼','Hello, how are you today?','你好，今天过得怎么样？',NULL,'interjection','初中','2026-07-01 12:23:56','2026-07-03 12:06:13',0),(2,'en',1,'goodbye','/ɡʊdBAɪ/',NULL,'再见','Goodbye, see you tomorrow!','再见，明天见！',NULL,'interjection','小学','2026-07-01 12:23:56','2026-07-03 12:06:13',0),(3,'en',1,'thank you','/θæŋk juː/',NULL,'谢谢你','Thank you for your help.','谢谢你的帮助。',NULL,'phrase','小学','2026-07-01 12:23:56','2026-07-03 12:06:13',0),(4,'en',1,'please','/pliːz/',NULL,'请','Please sit down.','请坐。',NULL,'interjection','初中','2026-07-01 12:23:56','2026-07-03 12:13:26',0),(5,'en',1,'sorry','/Sɒri/',NULL,'对不起','I am sorry for being late.','抱歉我迟到了。',NULL,'adjective','初中','2026-07-01 12:23:56','2026-07-03 12:06:13',0),(6,'en',1,'friend','/frend/',NULL,'朋友','She is my best friend.','她是我最好的朋友。',NULL,'noun','高中','2026-07-01 12:23:56','2026-07-03 12:06:13',0),(7,'en',1,'family','/Fæməli/',NULL,'家庭','I love my family.','我爱我的家人。',NULL,'noun','高中','2026-07-01 12:23:56','2026-07-03 12:06:13',0),(8,'en',1,'water','/Wɔːtər/',NULL,'水','Can I have a glass of water?','我能要一杯水吗？',NULL,'noun','CET4','2026-07-01 12:23:56','2026-07-03 12:06:13',0),(9,'en',1,'food','/fuːd/',NULL,'食物','The food here is delicious.','这里的食物很美味。',NULL,'noun','小学','2026-07-01 12:23:56','2026-07-03 12:06:13',0),(10,'en',1,'book','/bʊk/',NULL,'书','I am reading a book.','我正在读一本书。',NULL,'noun','高中','2026-07-01 12:23:56','2026-07-03 12:06:13',0),(11,'en',1,'school','/skuːl/',NULL,'学校','I go to school every day.','我每天去学校。',NULL,'noun','初中','2026-07-01 12:23:56','2026-07-03 12:06:13',0),(12,'en',1,'teacher','/Tiːtʃər/',NULL,'老师','My teacher is very kind.','我的老师很和蔼。',NULL,'noun','小学','2026-07-01 12:23:56','2026-07-03 12:06:13',0),(13,'en',1,'student','/Stuːdənt/',NULL,'学生','He is a good student.','他是一个好学生。',NULL,'noun','初中','2026-07-01 12:23:56','2026-07-03 12:06:13',0),(14,'en',1,'happy','/Hæpi/',NULL,'快乐的','I feel very happy today.','今天我感到很快乐。',NULL,'adjective','CET4','